package modulo2;

public class ExercicioSecao9 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		System.out.println("Crie duas variáveis inteiras.\r\n"
				+ "Teste todas as relações operacionais");
		int a= 32;
		int b = 6;
		System.out.println(+(a)+" é maior que "+(b) +"? "+ (a>b)+"\n" 
				+(a)+" é menor que "+(b) +"? "+ (a<b)+"\n" 
				+(a)+" é maior ou igual que "+(b) +"? "+ (a>=b)+"\n"
				+(a)+" é menor ou igual que "+(b) +"? "+ (a<=b)+"\n"
				+(a)+" é igual a "+(b) +"? "+ (a==b)+"\n" 
				+(a)+" é diferente que "+(b) +"? "+ (a!=b)) ;
	}

}
